void CUWrapperCommManager::recvDataCallback(pVOID p)
{
    Debug::trace("CUWrapperCommManager.UsbIrp", "recvDataCallback");

    pUSB_IRP pIrp = (pUSB_IRP) p;
    CUWrapperCommManager *pCUComm = (CUWrapperCommManager *)pIrp->userPtr;

    if (pIrp->result == OK)
    {
        int i = 0;
        while (pIrp->bfrList[i].actLen == pCUComm->ep1_PacketSize_)
        {
            // do all the full buffers
            memcpy(&pCUComm->evolutionMessage_[pCUComm->evolutionMessLen_], &pCUComm->bfrIN_[i], pIrp->bfrList[i].actLen);
            pCUComm->evolutionMessLen_ += pIrp->bfrList[i].actLen;

            Debug::trace("CUWrapperCommManager.IntData", HobString("Interrupt Transfer Data (IN): ") +
                    HobString(Hex::toString((const char *) pCUComm->bfrIN_[i], pIrp->bfrList[i].actLen)));

            i++;
        }

        // do the last buffer
        memcpy(&pCUComm->evolutionMessage_[pCUComm->evolutionMessLen_], &pCUComm->bfrIN_[i], pIrp->bfrList[i].actLen);
        pCUComm->evolutionMessLen_ += pIrp->bfrList[i].actLen;

        Debug::trace("CUWrapperCommManager.IntData", HobString("Interrupt Transfer Data (IN): ") +
                HobString(Hex::toString((const char *) pCUComm->bfrIN_[i], pIrp->bfrList[i].actLen)));

        pCUComm->recvdCUMessage_ = true;
        pCUComm->retryCount = 4;
    }
    else
    {
        pCUComm->retryInPipe = true;

        HobString count(Integer::toString(pCUComm->retryCount));
        Debug::trace("CUWrapperCommManager.Error", "recvDataCallback Not Successful. Will try recvUSBEvolHeaderIrp() again.  (" + count + ")");

        UsbManager::getInstance()->printUSBError(pIrp->result);
    }
}

void CUWrapperCommManager::recvUSBEvolHeaderIrp()
{
    Debug::trace("CUWrapperCommManager.UsbIrp", "recvUSBEvolHeaderIrp");

    memset (&irpIN_, 0, sizeof (irpIN_));

    irpIN_.irpLen = sizeof (irpIN_);
    irpIN_.userCallback = recvUSBEvolHeaderCallback;
    irpIN_.userPtr = this;
    irpIN_.transferLen = 10;
    irpIN_.bfrCount = 1;
    irpIN_.timeout = USB_TIMEOUT_NONE;
    irpIN_.bfrList [0].pid = USB_PID_IN;
    irpIN_.bfrList [0].pBfr = bfrIN_[0];
    irpIN_.bfrList [0].bfrLen = 10;

    int result = UsbManager::getInstance()->transferData(inPipeHandle_, &irpIN_);

    if (result != OK)
    {
        retryInPipe = true;

        HobString count(Integer::toString(retryCount));
        Debug::trace("CUWrapperCommManager.Error", "recvUSBEvolHeaderIrp Not Successful. Will try recvUSBEvolHeaderIrp() again.  (" + count + ")");

        UsbManager::getInstance()->printUSBError(result);


    }
}

void CUWrapperCommManager::recvDataIrp(UINT16 dataLength)
{
    Debug::trace("CUWrapperCommManager.UsbIrp", HobString("recvDataIrp -- dataLength: ") + HobString(Integer::toString(dataLength)));

    UINT16 numPackets = ((dataLength + (ep1_PacketSize_)) / ep1_PacketSize_); // allow for zero length packet
    int irpLength = sizeof(USB_IRP) + (sizeof (USB_BFR_LIST) * (numPackets - 1));

    memset (&irpIN_, 0, irpLength);

    irpIN_.irpLen = irpLength;
    irpIN_.userCallback = recvDataCallback;
    irpIN_.userPtr = this;
    irpIN_.transferLen = dataLength;
    irpIN_.bfrCount = numPackets;
    irpIN_.timeout = USB_TIMEOUT_NONE;

    int i = 0;
    while (i < numPackets - 1)
    {
        irpIN_.bfrList [i].pid = USB_PID_IN;
        irpIN_.bfrList [i].pBfr = bfrIN_[i];
        irpIN_.bfrList [i].bfrLen = ep1_PacketSize_;

        i++;
    }

    irpIN_.bfrList [i].pid = USB_PID_IN;
    irpIN_.bfrList [i].pBfr = bfrIN_[i];
    irpIN_.bfrList [i].bfrLen = dataLength - ((numPackets - 1) * ep1_PacketSize_);

    int result = UsbManager::getInstance()->transferData(inPipeHandle_, &irpIN_);

    if (result != OK)
    {
        retryInPipe = true;

        HobString count(Integer::toString(retryCount));
        Debug::trace("CUWrapperCommManager.Error", "recvDataIrp Not Successful. Will try recvUSBEvolHeaderIrp() again.  (" + count + ")");

        UsbManager::getInstance()->printUSBError(result);

    }
}

static const unsigned long maxIntXferSize = 64;

void CUWrapperCommManager::sendUSBEvolHeaderCallback(pVOID p)
{
    Debug::trace("CUWrapperCommManager.UsbIrp", "sendUSBEvolHeaderCallback");

    pUSB_IRP pIrp = (pUSB_IRP) p;
    CUWrapperCommManager *pCUComm = (CUWrapperCommManager *)pIrp->userPtr;

    if (pIrp->result == OK)
    {
        UINT32 size = pCUComm->usbEvolHdr_.getMessageLength();

        Debug::trace("CUWrapperCommManager.UsbIrp", HobString("calculate packet size = ") + Integer::toString(size));

        pCUComm->sendBodySize_ = size;

        pCUComm->bytesToSend = size;
        //pCUComm->sendDataIrp(size);//plus first 4 bytes and last 2 bytes
    }
    else
    {
        Debug::trace("CUWrapperCommManager.Error", "sendUSBEvolHeaderCallback Irp Not Successful");
        UsbManager::getInstance()->printUSBError(pIrp->result);

        pCUComm->pIntData_ = NULL;
        pCUComm->intDataLength_ = 0;

        pCUComm->xmitting_ = false;
    }
}

void CUWrapperCommManager::sendDataCallback(pVOID p)
{
    Debug::trace("CUWrapperCommManager.UsbIrp", "sendDataCallback");

    pUSB_IRP pIrp = (pUSB_IRP) p;
    CUWrapperCommManager *pCUComm = (CUWrapperCommManager *)pIrp->userPtr;
    bool update = false;

    if (pIrp->result == S_usbHcdLib_TIMEOUT)
    {
        Debug::trace("CUWrapperCommManager.IntData", "Int Transfer ERROR: S_usbHcdLib_TIMEOUT");
        Debug::trace("CUWrapperCommManager.IntData", HobString("Needed Transfered: ") +
                HobString(Integer::toString(pCUComm->irpOUT_.bfrList [0].bfrLen)));
        Debug::trace("CUWrapperCommManager.IntData", HobString("Actual Transfered: ") +
                HobString(Integer::toString(pCUComm->irpOUT_.bfrList [0].actLen)));
    }

    if (pIrp->result == OK)
    {
        pCUComm->intDataLength_ -= pCUComm->irpOUT_.bfrList [0].actLen;

        pCUComm->bytesSentSoFar += pCUComm->bytesToSend;
        pCUComm->bytesToSend = 0;

        if (pCUComm->lastSRecord_ || (pCUComm->intDataLength_ <= 0))
        {
            Debug::trace("CUWrapperCommManager.LastSRecord", "***Completed last Record***");
            pCUComm->pIntData_ = NULL;
            pCUComm->intDataLength_ = 0;
            if (pCUComm->lastSRecord_)
                update = true;                  //      Flush out the remaining information since we are done.
        }
        else
        {
            pCUComm->pIntData_ = (UINT8 *) ((UINT32) pCUComm->pIntData_ + (UINT32) pCUComm->irpOUT_.bfrList [0].actLen);
        }
        pCUComm->checkUpgradeProgress(update);
    }
    else
    {
        Debug::trace("CUWrapperCommManager.Error", "sendDataCallback Irp Not Successful");
        UsbManager::getInstance()->printUSBError(pIrp->result);

        pCUComm->pIntData_ = NULL;
        pCUComm->intDataLength_ = 0;

    }

    pCUComm->xmitting_ = false;

}

void CUWrapperCommManager::sendUSBEvolHdrIrp()
{
    UINT32 size = 0;

#if 0
    HobString msgDebug("sendUSBEvolHdrIrp:  pIntData_ = ");
    msgDebug.append(Hex::toString((long) pIntData_));
    msgDebug.append("  sizeModeSRecord_ = ").append(Bool::toString(sizeModeSRecord_));
    Debug::trace("CUWrapperCommManager.UsbIrp", msgDebug);
#endif
    xmitting_ = true;
    lastSRecord_ = false;

    //this is for transmitting firmware in s record format.
    //each packet will contain exactly one s record.
    //thus s records cannot be larger than 64 bytes.
    //the size of the packet is the size of the current s record.
    //the size of the s record is in the s record data.
    if (sizeModeSRecord_)
    {

        if (pIntData_[0] != 'S')
        {
            Debug::trace("CUWrapperCommManager.Error", "***In Srecord Mode but not Srecord***");
            pIntData_ = 0;
            intDataLength_ = 0;

            xmitting_ = false;
            return;
        }

        sscanf((const char *)(pIntData_ + 2), "%02X", &size);
        size *= 2;
        size += 6;
        //clip the s record to 64 bytes.
        if (size > maxIntXferSize)
            size = maxIntXferSize;

        if ((pIntData_[0] == 'S') && (pIntData_[1] == '7'))
        {

            Debug::trace("CUWrapperCommManager.LastSRecord", "***S7 found***");
            codeUpdaterStateMachine_ = LAST_SRECORD_SENT;
            lastSRecord_ = true;
        }

    }
    else
    {
        size = min(maxIntXferSize, intDataLength_);
    }

    usbEvolHdr_.setMessageLength(size);
    usbEvolHdr_.Serialize((char *) bfrCommHdrOUT_, true);

    memset (&irpOUT_, 0, sizeof(USB_IRP));

    irpOUT_.irpLen = sizeof(USB_IRP);
    irpOUT_.userCallback = sendUSBEvolHeaderCallback;
    irpOUT_.userPtr = this;
    irpOUT_.transferLen = 10;
    irpOUT_.bfrCount = 1;
    //  irpOUT_.timeout = USB_TIMEOUT_NONE;
    irpOUT_.timeout = intXferTimeOut_;//5000;

    irpOUT_.bfrList [0].pid = USB_PID_OUT;
    irpOUT_.bfrList [0].pBfr = bfrCommHdrOUT_;
    irpOUT_.bfrList [0].bfrLen = 10;

    Debug::trace("CUWrapperCommManager.IntData", HobString("Interrupt Transfer Header (OUT): ") +
            HobString(Hex::toString((const char *) bfrCommHdrOUT_, irpOUT_.bfrList [0].bfrLen)));
    Debug::trace("CUWrapperCommManager.IntData", HobString("out pipe endpoint id: ") + Integer::toString(pOutInterrupt_->endpointAddress));

    int result = UsbManager::getInstance()->transferData(outPipeHandle_, &irpOUT_);

    if (result != OK)
    {
        Debug::trace("CUWrapperCommManager.Error", "sendHeaderIrp Irp Not Successful");
        UsbManager::getInstance()->printUSBError(result);

        intDataLength_ = 0;
        xmitting_ = false;
        pIntData_ = NULL;
    }

}

void CUWrapperCommManager::sendDataIrp(UINT32 dataLength)
{
    Debug::trace("CUWrapperCommManager.UsbIrp", "sendDataIrp");

    memset (&irpOUT_, 0, sizeof(USB_IRP));

    irpOUT_.irpLen = sizeof(USB_IRP);
    irpOUT_.userCallback = sendDataCallback;
    irpOUT_.userPtr = this;
    irpOUT_.transferLen = dataLength;
    irpOUT_.bfrCount = 1;
    //  irpOUT_.timeout = USB_TIMEOUT_NONE;
    irpOUT_.timeout = intXferTimeOut_;//5000;

    irpOUT_.bfrList [0].pid = USB_PID_OUT;
    irpOUT_.bfrList [0].pBfr = pIntData_;
    irpOUT_.bfrList [0].bfrLen = dataLength;

    int result = UsbManager::getInstance()->transferData(outPipeHandle_, &irpOUT_);

    if (result != OK)
    {
        Debug::trace("CUWrapperCommManager.Error", "sendDataIrp Irp Not Successful");
        UsbManager::getInstance()->printUSBError(result);
    }
}
